import type { L4, Level, Word, WordCategory } from './types'

// Spelling: see docs/BAERNDUETSCH.md (Dieth-near, l-vocalisation written as "u", ‹y› for old long î).
// Verification status per word: content/be-review.json (generated by scripts/verify-be.ts + manual decisions).

type Extra = { illu?: string; sound?: L4; key?: string }
function w(id: string, cat: WordCategory, level: Level, be: string, de: string, pl: string, en: string, extra: Extra = {}): Word {
  return { id, cat, level, text: { be, de, pl, en }, illu: extra.illu ?? id, sound: extra.sound, key: extra.key }
}
const s = (be: string, de: string, pl: string, en: string): L4 => ({ be, de, pl, en })

